cat > /tmp/test-formula.mjs << 'EOF'
// Test the compileFormula function
function compileFormula(formula, labels) {
  const sorted = labels.slice().sort((a, b) => b.label.length - a.label.length);
  let e = ' ' + formula + ' ';
  for (const f of sorted) e = e.replace(new RegExp(' ' + f.label + ' ', 'g'), ` @${f.idx}@ `);
  const residue = e.replace(/@\d+@/g, ' ').replace(/[0-9.+\-*/()\s,]/g, '').replace(/\b(min|max)\b/g, '');
  if (residue.trim().length) {
    console.log(`Residue check failed: residue='${residue.trim()}'`);
    return null;
  }
  const dart = e.replace(/@(\d+)@/g, "(num.tryParse(_v[$1] ?? '') ?? 0)").trim();
  return /@|[֐-׿]/.test(dart) ? null : (dart || null);
}

const labels = [
  { label: 'שכירות', idx: 3 },
  { label: 'חודשים', idx: 4 },
  { label: 'שכירות לשנה', idx: 5 },
  { label: 'תקרה לפי 3 חודשים', idx: 6 },
  { label: 'תקרה לפי שליש', idx: 7 },
  { label: 'תקרה נמוכה', idx: 8 }
];

const formula = 'min(תקרה לפי 3 חודשים, תקרה לפי שליש)';
console.log(`Testing formula: ${formula}`);
const result = compileFormula(formula, labels);
console.log(`Result: ${result}`);
EOF
node /tmp/test-formula.mjs
